where.if:
AND EXISTS (
SELECT 1 FROM recipe_category rc
WHERE rc.recipe_id = r.id AND rc.category_id = #{categoryId}
)

mapper.select:
SELECT r.id, r.title, r.score, r.description, (SELECT CONCAT(#{imgBaseUrl}, im.stored_name) FROM images_record ir LEFT JOIN image_management im ON ir.image_id = im.id WHERE ir.recipe_id = r.id ORDER BY ir.sort ASC, ir.create_time ASC LIMIT 1) AS imgUrl, COUNT(ri.id) AS matchCount FROM recipes r INNER JOIN recipe_ingredients ri ON r.id = ri.recipe_id WHERE ri.category_id IN
#{id}
GROUP BY r.id, r.title, r.score ORDER BY matchCount DESC, r.score DESC
